  function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));floorDraw();const sorted=[...enemies.filter(e=>!e.dead)].sort((a,b)=>a.y-b.y);for(const e of sorted)drawEnemy(e);drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;for(const f of floating){ctx.globalAlpha=clamp(f.life/f.max,0,1);ctx.fillStyle=f.color;ctx.font='700 12px DM Sans';ctx.textAlign='center';ctx.shadowColor='#171020';ctx.shadowBlur=5;ctx.fillText(f.text,f.x,f.y);ctx.shadowBlur=0}ctx.globalAlpha=1;ctx.restore();}
  function loop(ts){const dt=Math.min(.04,(ts-last)/1000||0);last=ts;update(dt);render();requestAnimationFrame(loop)}requestAnimationFrame(loop);
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k===' '||k==='j')attack();if(k==='q')dash();if(k==='e')burst();if(k==='enter'&&gameState==='menu')startGame()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
  $('startBtn').onclick=startGame;$('retryBtn').onclick=startGame;$('victoryBtn').onclick=startGame;$('skipUpgrade').onclick=()=>continueFloor(null);$('soundBtn').onclick=()=>{audioOn=!audioOn;$('soundBtn').innerHTML=audioOn?'♫ <span>ACTIVO</span>':'♫ <span>SONIDO</span>';if(audioOn)sound(440,.1,'sine')};
  $('mobileAttack').addEventListener('pointerdown',e=>{e.preventDefault();attack()});$('mobileDash').addEventListener('pointerdown',e=>{e.preventDefault();dash()});$('mobileBurst').addEventListener('pointerdown',e=>{e.preventDefault();burst()});document.querySelectorAll('[data-dir]').forEach(b=>{const d=b.dataset.dir,map={up:'w',down:'s',left:'a',right:'d'};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(map[d])});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete(map[d]));});
